using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// Controls floating visual feedback popups when collecting or sorting river waste.
/// Supports WCAG 2.2 accessibility through high-contrast visual cues paired with audio feedback.
/// </summary>
public class WastePopupVFX : MonoBehaviour
{
    // Generated by AI
    [Header("Animation Settings")]
    [SerializeField] private float floatSpeed = 1.5f;
    [SerializeField] private float fadeDuration = 0.85f;
    [SerializeField] private float canvasDriftHeight = 85f;

    // Generated by AI
    [Header("UI References")]
    [SerializeField] private TextMeshProUGUI popupText;
    [SerializeField] private Text legacyPopupText;
    [SerializeField] private CanvasGroup canvasGroup;

    private RectTransform rectTransform;
    private Vector2 startAnchoredPos;
    private bool useCanvasDrift = false;

    // Generated by AI
    /// <summary>
    /// Initializes the popup message, color contrast, and starts the fade-out coroutine (TMP).
    /// </summary>
    public void ShowPopup(string message, Color highContrastColor)
    {
        useCanvasDrift = false;
        if (popupText != null)
        {
            popupText.text = message;
            popupText.color = highContrastColor;
        }

        StartCoroutine(AnimateAndFadeRoutine());
    }

    /// <summary>
    /// Initializes the floating popup for UnityEngine.UI.Text elements inside the game Canvas.
    /// </summary>
    public void ShowLegacyPopup(Text uiText, CanvasGroup group, string message, Color highContrastColor, Vector2 startPos)
    {
        legacyPopupText = uiText;
        canvasGroup = group;
        rectTransform = GetComponent<RectTransform>();
        startAnchoredPos = startPos;
        useCanvasDrift = true;

        if (legacyPopupText != null)
        {
            legacyPopupText.text = message;
            legacyPopupText.color = highContrastColor;
        }

        if (canvasGroup != null)
        {
            canvasGroup.alpha = 1f;
        }

        StartCoroutine(AnimateAndFadeRoutine());
    }

    // Generated by AI
    private IEnumerator AnimateAndFadeRoutine()
    {
        float elapsedTime = 0f;

        while (elapsedTime < fadeDuration)
        {
            elapsedTime += Time.deltaTime;
            float t = Mathf.Clamp01(elapsedTime / fadeDuration);

            if (useCanvasDrift && rectTransform != null)
            {
                // Smooth upward drift + subtle elastic pop for Canvas UI elements
                float yOffset = Mathf.Sin(t * Mathf.PI * 0.5f) * canvasDriftHeight;
                rectTransform.anchoredPosition = startAnchoredPos + new Vector2(0f, yOffset);

                float punch = t < 0.2f
                    ? Mathf.Lerp(0.6f, 1.25f, t / 0.2f)
                    : Mathf.Lerp(1.25f, 1.0f, (t - 0.2f) / 0.8f);
                rectTransform.localScale = new Vector3(punch, punch, 1f);
            }
            else
            {
                // Move the popup upward smoothly each frame
                transform.Translate(Vector3.up * floatSpeed * Time.deltaTime);
            }

            // Gradually reduce alpha transparency for smooth fade-out
            if (canvasGroup != null)
            {
                canvasGroup.alpha = t > 0.55f ? Mathf.Lerp(1f, 0f, (t - 0.55f) / 0.45f) : 1f;
            }

            yield return null;
        }

        Destroy(gameObject);
    }
}
